@SpringBootTest(properties="project.current-user.development-enabled=false") @AutoConfigureMockMvc @ActiveProfiles("test") @Testcontainers(disabledWithoutDocker=true)
class ProjectPortfolioSnapshotIntegrationTest {
	@Container @ServiceConnection static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17");
	@Autowired MockMvc mvc; @Autowired JdbcTemplate jdbc; @Autowired JwtProvider jwt; @Autowired ObjectMapper mapper;
	@MockitoBean RefreshTokenStore refresh;
	@MockitoBean(name="projectClock") Clock clock;
	@MockitoSpyBean ProjectPortfolioRepository portfolios;
	@MockitoSpyBean ProjectApplicationPortfolioSnapshotRepository snapshots;
	String token(long id){return "Bearer "+jwt.createAccessToken(id+"@link.test",id==101?"PREMIUM":"USER");}
	@BeforeEach void fixtures() throws Exception {
		jdbc.execute("CREATE TABLE IF NOT EXISTS portfolios(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),title VARCHAR(255) NOT NULL,thumbnail_url VARCHAR(2048),topic VARCHAR(255),summary TEXT,description TEXT,role VARCHAR(100),tech_stack JSONB,attachments JSONB,visibility VARCHAR(20) NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL)");
		jdbc.update("DELETE FROM project_application_portfolio_snapshots");jdbc.update("DELETE FROM project_application_portfolios");jdbc.update("DELETE FROM project_applications");jdbc.update("DELETE FROM project_members");jdbc.update("DELETE FROM projects");jdbc.update("DELETE FROM portfolios");jdbc.update("DELETE FROM users");
		jdbc.execute(Files.readString(Path.of("../docs/sql/project-portfolio-snapshots.sql")));
		for(long id:new long[]{101,202,303})jdbc.update("INSERT INTO users(id,email,nickname,tag,role,status) VALUES(?,?,?,?,?,?)",id,id+"@link.test","개발자"+id,"link-"+id,id==101?"PREMIUM":"USER","ACTIVE");
		when(clock.getZone()).thenReturn(ZoneId.of("Asia/Seoul"));when(clock.instant()).thenReturn(Instant.parse("2026-11-06T03:00:00Z"));
	}
	Map<String,Object> input(){return new LinkedHashMap<>(Map.of("title","지원 포트폴리오","summary","한 줄 소개","role","백엔드","techStack",List.of("Java"),"description","제출 당시의 프로젝트 설명","visibility","PUBLIC"));}
	JsonNode portfolio(long user,String visibility) throws Exception {
		var value=input();value.put("visibility",visibility);
		return mapper.readTree(mvc.perform(post("/api/v1/portfolios").header("Authorization",token(user)).contentType("application/json").content(mapper.writeValueAsString(value))).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());
	}
	long id(JsonNode p){return p.path("portfolio").path("id").asLong();}
	long project() throws Exception {
		var body=new LinkedHashMap<String,Object>(Map.of("title","포트폴리오 연동 프로젝트","description","실제 포트폴리오를 연결합니다.","imageUrl","https://example.test/a.png","isPublic",true,"recruitmentSlots",List.of(Map.of("roleCode","BACKEND","capacity",3,"minimumYears",0)),"techStacks",List.of("Java"),"interests",List.of("교육"),"recruitmentStart","2026-11-01","recruitmentEnd","2026-11-20","developmentStart","2026-11-06"));body.put("developmentEnd","2026-12-30");
		return mapper.readTree(mvc.perform(post("/api/v1/projects").header("Authorization",token(101)).contentType("application/json").content(mapper.writeValueAsString(body))).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString()).path("id").asLong();
	}
	org.springframework.test.web.servlet.ResultActions apply(long project,List<Long> ids) throws Exception {
		return mvc.perform(post("/api/v1/projects/"+project+"/applications").header("Authorization",token(202)).contentType("application/json").content(mapper.writeValueAsString(Map.of("jobRole","BACKEND","portfolioIds",ids,"introduction","프로젝트에 함께 참여하고 싶습니다."))));
	}
	org.springframework.test.web.servlet.ResultActions edit(JsonNode before) throws Exception {
		var value=input();value.put("description","변경한 설명");value.put("expectedUpdatedAt",before.path("portfolio").path("updatedAt").asString());
		return mvc.perform(put("/api/v1/portfolios/"+id(before)).header("Authorization",token(202)).contentType("application/json").content(mapper.writeValueAsString(value)));
	}

	String snapshotPath(long project,long application,long snapshot){return "/api/v1/projects/"+project+"/applications/"+application+"/portfolios/"+snapshot;}
	JsonNode submitted(long project,JsonNode original) throws Exception {return mapper.readTree(apply(project,List.of(id(original))).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());}
	long snapshotId(JsonNode application){return application.path("submittedPortfolios").get(0).path("id").asLong();}
	@Test void onlyOwnPublicPortfoliosAreEligible() throws Exception {
		long project=project();var own=portfolio(202,"PUBLIC");var hidden=portfolio(202,"PRIVATE");var foreign=portfolio(303,"PUBLIC");
		mvc.perform(get("/api/v1/projects/"+project+"/application-options").header("Authorization",token(202))).andExpect(status().isOk()).andExpect(jsonPath("$.canApply").value(true)).andExpect(jsonPath("$.portfolios.length()").value(1)).andExpect(jsonPath("$.portfolios[0].id").value(id(own)));
		for(long invalid:new long[]{id(hidden),id(foreign),999999})apply(project,List.of(invalid)).andExpect(status().isForbidden());
		apply(project,List.of(id(own),id(own))).andExpect(status().isBadRequest());
		assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM project_application_portfolio_snapshots",Integer.class));
	}
	@Test void emptyPublicListExplainsWhyApplicationIsDisabled() throws Exception {
		long project=project();portfolio(202,"PRIVATE");
		mvc.perform(get("/api/v1/projects/"+project+"/application-options").header("Authorization",token(202))).andExpect(status().isOk()).andExpect(jsonPath("$.canApply").value(false)).andExpect(jsonPath("$.portfolios.length()").value(0));
	}
	@Test void originalCanBeEditedAndDeletedWhileSubmissionRemains() throws Exception {
		long project=project();var original=portfolio(202,"PUBLIC");var application=submitted(project,original);long app=application.path("id").asLong(),snapshot=snapshotId(application);
		mvc.perform(get("/api/v1/portfolios/"+id(original)).header("Authorization",token(202))).andExpect(status().isOk()).andExpect(jsonPath("$.canEdit").value(true));
		edit(original).andExpect(status().isOk());
		mvc.perform(delete("/api/v1/portfolios/"+id(original)).header("Authorization",token(202))).andExpect(status().isNoContent());
		mvc.perform(get("/api/v1/portfolios/"+id(original)).header("Authorization",token(202))).andExpect(status().isNotFound());
		mvc.perform(get(snapshotPath(project,app,snapshot)).header("Authorization",token(202))).andExpect(status().isOk()).andExpect(jsonPath("$.description").value("제출 당시의 프로젝트 설명")).andExpect(jsonPath("$.canEdit").value(false));
		mvc.perform(get("/api/v1/projects/"+project+"/application-options").header("Authorization",token(202))).andExpect(status().isOk()).andExpect(jsonPath("$.application.portfolioIds[0]").value(id(original))).andExpect(jsonPath("$.application.submittedPortfolios[0].id").value(snapshot));
		assertNull(jdbc.queryForObject("SELECT portfolio_id FROM project_application_portfolios WHERE application_id=?",Long.class,app));
		assertEquals(id(original),jdbc.queryForObject("SELECT source_portfolio_id FROM project_application_portfolio_snapshots WHERE id=?",Long.class,snapshot));
	}
	@Test void copiesRetainImagesLinksAndRichDocument() throws Exception {
		var value=input();value.put("thumbnailUrl","https://example.test/cover.png");value.put("attachments",List.of(Map.of("name","설계 문서","url","https://example.test/design.pdf")));
		value.put("document",Map.of("schema","devmozip.portfolio.v1","start","2026-01","end","2026-02","teamSize","3명","fields",List.of("웹","교육"),"blocks",List.of(
			Map.of("id","contribution","kind","text","title","나의 기여","format","markdown","content","백엔드 설계와 구현","images",List.of(),"links",List.of()),
			Map.of("id","gallery","kind","gallery","title","결과물","content","","format","markdown","images",List.of(Map.of("src","https://example.test/screen.png","caption","실행 화면")),"links",List.of()),
			Map.of("id","links","kind","links","title","프로젝트 링크","content","","format","markdown","images",List.of(),"links",List.of(Map.of("id","github","label","GitHub","url","https://example.test/repo"))))));
		var original=mapper.readTree(mvc.perform(post("/api/v1/portfolios").header("Authorization",token(202)).contentType("application/json").content(mapper.writeValueAsString(value))).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());
		long project=project();var application=submitted(project,original);mvc.perform(delete("/api/v1/portfolios/"+id(original)).header("Authorization",token(202))).andExpect(status().isNoContent());
		var copy=mapper.readTree(mvc.perform(get(snapshotPath(project,application.path("id").asLong(),snapshotId(application))).header("Authorization",token(101))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());
		assertEquals(original.path("document"),copy.path("document"));assertEquals(original.path("attachments"),copy.path("attachments"));assertEquals(original.path("portfolio"),copy.path("portfolio"));assertFalse(copy.path("canEdit").asBoolean());
	}
	@Test void keepsSubmittedCopiesAfterCancellationAndRejectionAndEnforcesThree() throws Exception {
		long project=project();var a=portfolio(202,"PUBLIC");var b=portfolio(202,"PUBLIC");var c=portfolio(202,"PUBLIC");var d=portfolio(202,"PUBLIC");
		apply(project,List.of(id(a),id(b),id(c),id(d))).andExpect(status().isBadRequest());
		var application=mapper.readTree(apply(project,List.of(id(a),id(b),id(c))).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());long app=application.path("id").asLong();
		mvc.perform(patch("/api/v1/projects/"+project+"/applications/"+app).header("Authorization",token(202)).contentType("application/json").content("{\"status\":\"CANCELLED\"}")).andExpect(status().isOk());
		mvc.perform(get(snapshotPath(project,app,snapshotId(application))).header("Authorization",token(202))).andExpect(status().isOk());
		var another=submitted(project(),a);long otherProject=another.path("projectId").asLong(),otherApp=another.path("id").asLong();
		mvc.perform(patch("/api/v1/projects/"+otherProject+"/applications/"+otherApp).header("Authorization",token(101)).contentType("application/json").content("{\"status\":\"REJECTED\",\"rejectionReason\":\"다음 기회에 함께해요.\"}")).andExpect(status().isOk());
		mvc.perform(get(snapshotPath(otherProject,otherApp,snapshotId(another))).header("Authorization",token(202))).andExpect(status().isOk());
		assertEquals(4,jdbc.queryForObject("SELECT count(*) FROM project_application_portfolio_snapshots",Integer.class));
		apply(project,List.of(id(a))).andExpect(status().isConflict());
	}
	@Test void onlyApplicantAndPremiumHostCanReadAndCannotUseOtherApplicationPath() throws Exception {
		long project=project();var application=submitted(project,portfolio(202,"PUBLIC"));String path=snapshotPath(project,application.path("id").asLong(),snapshotId(application));
		mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).header("Authorization",token(303))).andExpect(status().isNotFound());
		mvc.perform(get(path).header("Authorization",token(101))).andExpect(status().isOk());
		mvc.perform(get(snapshotPath(project+1000,application.path("id").asLong(),snapshotId(application))).header("Authorization",token(202))).andExpect(status().isNotFound());
		jdbc.update("UPDATE users SET role='USER' WHERE id=101");
		mvc.perform(get(path).header("Authorization",token(101))).andExpect(status().isForbidden());mvc.perform(get(path).header("Authorization",token(202))).andExpect(status().isOk());
	}
	@Test void snapshotFailureRollsBackApplicationAndLinks() throws Exception {
		long project=project();var original=portfolio(202,"PUBLIC");
		doThrow(new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"테스트 저장 실패")).when(snapshots).saveAndFlush(any(ProjectApplicationPortfolioSnapshot.class));
		apply(project,List.of(id(original))).andExpect(status().isServiceUnavailable());
		for(String table:List.of("project_applications","project_application_portfolios","project_application_portfolio_snapshots"))assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM "+table,Integer.class));
		edit(original).andExpect(status().isOk());
	}
	@Test void concurrentOriginalEditIsSerializedAndDoesNotRewriteSubmittedCopy() throws Exception {
		long project=project();var original=portfolio(202,"PUBLIC");var locked=new CountDownLatch(1);var release=new CountDownLatch(1);
		doAnswer(invocation->{var result=invocation.callRealMethod();locked.countDown();assertTrue(release.await(15,TimeUnit.SECONDS));return result;}).when(portfolios).lockOwnedPublic(eq(202L),anyList());
		try(var executor=Executors.newFixedThreadPool(2)){
			var submission=executor.submit(()->submitted(project,original));assertTrue(locked.await(15,TimeUnit.SECONDS));var editing=executor.submit(()->edit(original).andReturn().getResponse().getStatus());
			assertThrows(TimeoutException.class,()->editing.get(250,TimeUnit.MILLISECONDS));release.countDown();var app=submission.get(15,TimeUnit.SECONDS);assertEquals(200,editing.get(15,TimeUnit.SECONDS));
			mvc.perform(get(snapshotPath(project,app.path("id").asLong(),snapshotId(app))).header("Authorization",token(202))).andExpect(status().isOk()).andExpect(jsonPath("$.description").value("제출 당시의 프로젝트 설명"));
		}finally{release.countDown();}
	}

	@Test void concurrentDeleteWaitsForCompleteSubmittedCopy() throws Exception {
		long project=project();var original=portfolio(202,"PUBLIC");var locked=new CountDownLatch(1);var release=new CountDownLatch(1);
		doAnswer(invocation->{var result=invocation.callRealMethod();locked.countDown();assertTrue(release.await(15,TimeUnit.SECONDS));return result;}).when(portfolios).lockOwnedPublic(eq(202L),anyList());
		try(var executor=Executors.newFixedThreadPool(2)){
			var submission=executor.submit(()->submitted(project,original));assertTrue(locked.await(15,TimeUnit.SECONDS));
			var deletion=executor.submit(()->mvc.perform(delete("/api/v1/portfolios/"+id(original)).header("Authorization",token(202))).andReturn().getResponse().getStatus());
			assertThrows(TimeoutException.class,()->deletion.get(250,TimeUnit.MILLISECONDS));release.countDown();var app=submission.get(15,TimeUnit.SECONDS);assertEquals(204,deletion.get(15,TimeUnit.SECONDS));
			mvc.perform(get(snapshotPath(project,app.path("id").asLong(),snapshotId(app))).header("Authorization",token(202))).andExpect(status().isOk());
		}finally{release.countDown();}
	}
	@Test void migrationRefusesToInventMissingHistoricalContent() throws Exception {
		long project=project();var original=portfolio(202,"PUBLIC");var app=submitted(project,original);
		jdbc.update("DELETE FROM project_application_portfolio_snapshots");
		String migration=Files.readString(Path.of("../docs/sql/project-portfolio-snapshots.sql"));
		try(var connection=postgres.createConnection("")){try(var statement=connection.createStatement()){
			assertThrows(java.sql.SQLException.class,()->statement.execute(migration));statement.execute("ROLLBACK");
		}}
		mvc.perform(delete("/api/v1/portfolios/"+id(original)).header("Authorization",token(202))).andExpect(status().isConflict());
		assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM project_application_portfolios WHERE application_id=?",Integer.class,app.path("id").asLong()));
	}
	@Test void missingSetNullConstraintDisablesNewSubmissions() throws Exception {
		long project=project();var original=portfolio(202,"PUBLIC");jdbc.execute("ALTER TABLE project_application_portfolios DROP CONSTRAINT fk_project_application_portfolio");
		try{apply(project,List.of(id(original))).andExpect(status().isServiceUnavailable());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM project_applications",Integer.class));}
		finally{jdbc.execute(Files.readString(Path.of("../docs/sql/project-portfolio-snapshots.sql")));}
	}
}
